function predict(x){
  let s=0;
  for(const t of TREES){
    let n=0;
    while(n>=0){
      n = x[t.f[n]]<=t.t[n] ? t.l[n] : t.r[n];
    }
    s+=t.v[~n];
  }
  return 1/(1+Math.exp(-s));
}

function evaluate(details){
  if(!details||!details.underage) return null;
  const u=details.underage;
  const minor=u.minor||0;
  const x=new Array(FEATURES.length).fill(0);
  const ul=u.labels&&u.labels.underage||{};
  const al=u.labels&&u.labels.adult||{};
  for(const [k,v] of Object.entries(ul)){
    const i=FEATURES.indexOf(k);
    if(i>=0) x[i]=v;
  }
  for(const [k,v] of Object.entries(al)){
    const i=FEATURES.indexOf('adult__'+k);
    if(i>=0) x[i]=v;
  }
  const score=predict(x);
  const blocked=score>=0.45||minor>=0.72;
  return {score,blocked,minor};
}

module.exports={evaluate,predict,FEATURES};
